34	// rawJobCircuitEnvelope builds a complete committed envelope with the frozen,
35	// setup-bearing circuit "c" v1 and one job j1 whose circuit value is the
36	// given raw JSON string token (already quoted/escaped by the caller).
37	func rawJobCircuitEnvelope(circuitJSON string) []byte {
38		return []byte(`{"format":1,"circuits":[` +
39			`{"name":"c","version":1,"constraints":1,"public_inputs":1,"private_inputs":1,"frozen":true,"description":""}` +
40			`],"setups":[{"name":"c","version":1}],"jobs":[` +
41			`{"id":"j1","circuit":` + circuitJSON + `,"version":1,"kind":"prove","attempt":1}]}`)
42	}
