44	// rawJobCircuitRecordEnvelope wraps a single fully hand-written job record
45	// around the legal "c" v1 circuit, so the caller controls key spellings.
46	func rawJobCircuitRecordEnvelope(record string) []byte {
47		return []byte(`{"format":1,"circuits":[` +
48			`{"name":"c","version":1,"constraints":1,"public_inputs":1,"private_inputs":1,"frozen":true,"description":""}` +
49			`],"setups":[{"name":"c","version":1}],"jobs":[` + record + `]}`)
