66			"truncated multibyte":   "\"电路\xe4\xb8\"",
67			"lone high surrogate":   `"电路\uD800"`,
68			"lone low surrogate":    `"电路\uDC00"`,
69		}
70		for label, jobCircuit := range damaged {
71			t.Run(label, func(t *testing.T) {
72				raw := []byte(`{"format":1,"circuits":[` +
73					`{"name":"电路�","version":1,"constraints":1,"public_inputs":1,"private_inputs":1,"frozen":true,"description":""}` +
74					`],"setups":[{"name":"电路�","version":1}],"jobs":[` +
75					`{"id":"j-legal","circuit":"电路�","version":1,"kind":"prove","attempt":1},` +
76					`{"id":"j-bad","circuit":` + jobCircuit + `,"version":1,"kind":"prove","attempt":1}]}`)
