24	// rawJobCircuitLookalikeEnvelopeCLI builds a committed envelope with one
25	// genuinely frozen, setup-bearing circuit named "电路�" plus two jobs: one
26	// legal job owned by that circuit and one whose circuit token is the given
27	// raw JSON string that decodes onto the same name only by replacement.
28	func rawJobCircuitLookalikeEnvelopeCLI(damagedCircuitJSON string) []byte {
29		return []byte(`{"format":1,"circuits":[` +
30			`{"name":"电路�","version":1,"constraints":1,"public_inputs":1,"private_inputs":1,"frozen":true,"description":""}` +
31			`],"setups":[{"name":"电路�","version":1}],"jobs":[` +
32			`{"id":"j-legal","circuit":"电路�","version":1,"kind":"prove","attempt":1},` +
33			`{"id":"j-bad","circuit":` + damagedCircuitJSON + `,"version":1,"kind":"prove","attempt":1}]}`)
34	}
