37	// frozen circuit "c" v1 and one fully hand-written job record, so the caller
38	// controls the spelling of the circuit key.
39	func rawJobCircuitKeyEnvelopeCLI(record string) []byte {
40		return []byte(`{"format":1,"circuits":[` +
41			`{"name":"c","version":1,"constraints":1,"public_inputs":1,"private_inputs":1,"frozen":true,"description":""}` +
42			`],"setups":[{"name":"c","version":1}],"jobs":[` + record + `]}`)
